mapper.select:
select HACL.CLASS_LINE_ID, HACL.CLASS_HEAD_ID, HACL.CONTRACT_ID, HACL.CONTRACT_NUMBER, HACL.BUSINESS_TYPE, (select hbt.DESCRIPTION from HLS_BUSINESS_TYPE hbt where hbt.BUSINESS_TYPE = HACl.BUSINESS_TYPE and hbt.document_category = 'CONTRACT') as BUSINESS_TYPE_N, HACL.INITIAL_LEVEL, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'FIVE_CLASSIFICATION_RESULT' AND scb.CODE_ID = scv.CODE_ID and scv.value = HACL.INITIAL_LEVEL) INITIAL_LEVEL_N, HACL.REVIEW_LEVEL, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'FIVE_CLASSIFICATION_RESULT' AND scb.CODE_ID = scv.CODE_ID and scv.value = HACl.REVIEW_LEVEL) REVIEW_LEVEL_N, HACL.CONTRACT_AMOUNT, HACL.DELIVERY_TIME, TO_CHAR(HACL.DELIVERY_TIME, 'YYYY-MM-DD') DELIVERY_TIME_N, HACL.LEASE_TERM, HACL.REMAINING_RENT, HACL.REMAINING_PRINCIPAL, ( SELECT sum( nvl( ccc.principal, 0 ) - nvl( ccc.received_principal, 0 ) ) FROM con_contract cc, con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_type = 1 AND cc.CONTRACT_NUMBER = HACL.CONTRACT_NUMBER GROUP BY cc.CONTRACT_NUMBER ) AS REMAINING_PRINCIPAL_WO, HACL.REMAINING_MARGIN, HACL.OVERDUE_RENT, HACL.OVERDUE_DAYS, HACL.FX_OVERDUE_RENT, HACL.FX_OVERDUE_DAYS, HACL.PENALTY_INTEREST, HACL.remaining_exposure from HLS_ASSET_CLASS_LINE HACL
and HACL.CLASS_HEAD_ID = #{classHeadId}
and HACL.CONTRACT_NUMBER like #{contractNumber}
and HACl.BUSINESS_TYPE = #{businessType}
and HACL.INITIAL_LEVEL = #{initialLevel}
and HACl.REVIEW_LEVEL = #{reviewLevel}
and HACl.OVERDUE_DAYS = #{overdueDays}
and HACl.FX_OVERDUE_DAYS = #{fxOverdueDays}
and HACl.DELIVERY_TIME = to_date(#{deliveryTime},'yyyy-mm-dd')
and HACl.LEASE_TERM = #{leaseTerm}
and hacl.class_head_id IN ( select class_head_id from ( select class_head_id from hls_asset_class_head where bp_id = #{manufacturerId}
order by batch_num desc) where rownum <= 1 )

select HACL.CLASS_LINE_ID, HACL.CLASS_HEAD_ID, HACL.CONTRACT_ID, HACL.CONTRACT_NUMBER, HACL.BUSINESS_TYPE, (select hbt.DESCRIPTION from HLS_BUSINESS_TYPE hbt where hbt.BUSINESS_TYPE = HACl.BUSINESS_TYPE and hbt.document_category = 'CONTRACT') as BUSINESS_TYPE_N, HACL.approve_initial_level, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'ASSET_CLASS' AND scb.CODE_ID = scv.CODE_ID and scv.value = HACL.approve_initial_level) approve_initial_level_n, HACL.approve_review_level, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'ASSET_CLASS' AND scb.CODE_ID = scv.CODE_ID and scv.value = HACl.approve_review_level) APPROVE_REVIEW_LEVEL_N, HACL.CONTRACT_AMOUNT, HACL.DELIVERY_TIME, TO_CHAR(HACL.DELIVERY_TIME, 'YYYY-MM-DD') DELIVERY_TIME_N, HACL.LEASE_TERM, HACL.REMAINING_RENT, HACL.REMAINING_PRINCIPAL, ( SELECT sum( nvl( ccc.principal, 0 ) - nvl( ccc.received_principal, 0 ) ) FROM con_contract cc, con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_type = 1 AND cc.CONTRACT_NUMBER = HACL.CONTRACT_NUMBER GROUP BY cc.CONTRACT_NUMBER ) AS REMAINING_PRINCIPAL_WO, HACL.REMAINING_MARGIN, HACL.OVERDUE_RENT, HACL.OVERDUE_DAYS, HACL.FX_OVERDUE_RENT, HACL.FX_OVERDUE_DAYS, HACL.PENALTY_INTEREST, HACL.remaining_exposure from HLS_ASSET_CLASS_LINE HACL
and HACL.CLASS_HEAD_ID = #{classHeadId}
and HACL.CONTRACT_NUMBER like #{contractNumber}
and HACl.BUSINESS_TYPE = #{businessType}
and HACL.APPROVE_INITIAL_LEVEL = #{approveInitialLevel}
and HACl.APPROVE_REVIEW_LEVEL = #{approveReviewLevel}
and HACl.OVERDUE_DAYS = #{overdueDays}
and HACl.FX_OVERDUE_DAYS = #{fxOverdueDays}
and HACl.DELIVERY_TIME = to_date(#{deliveryTime},'yyyy-mm-dd')
and HACl.LEASE_TERM = #{leaseTerm}

SELECT *
FROM hls_asset_class_line hac



            and hac.class_line_id = #{classLineId}


            and hac.manufacturer_id = #{manufacturerId}
            and hac.class_head_id = #{classHeadId}
            and hac.review_level = #{reviewLevel}

SELECT *
FROM hls_asset_class_line hac

    and hac.manufacturer_id = #{manufacturerId}
    and hac.class_head_id = #{classHeadId}
    and hac.initial_level = #{initialLevel}

SELECT cc.contract_id, cc.contract_number, cc.manufacturer_id, cc.business_type, cc.lease_start_date DELIVERY_TIME, (select pq.lease_term_m from PRJ_QUOTATION pq where pq.QUOTATION_ID=cc.QUOTATION_ID) lease_term, cc.FINANCE_AMOUNT CONTRACT_AMOUNT, ( SELECT nvl ( sum( to_date ( sysdate ) - to_date ( ccc.due_date ) ), 0 ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_direction = 'INFLOW' AND ccc.cf_status = 'RELEASE' AND ccc.overdue_status = 'Y' ) overdue_days, ( SELECT nvl ( sum( nvl ( ccc.due_amount, 0 ) - nvl ( ccc.received_amount, 0 ) ), 0 ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_direction = 'INFLOW' AND ccc.cf_status = 'RELEASE' AND ccc.overdue_status = 'Y' ) overdue_rent, (select sum(nvl(ccc.FINE_DAYS,0)) from con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id ) FX_OVERDUE_DAYS, (select sum(nvl(ccc.FINE_DAYS,0)) from con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id ) FX_OVERDUE_RENT FROM con_contract cc
cc.contract_status in ('INCEPT','PENDING')
and cc.contract_id in
#{contract.contractId}
and cc.manufacturer_id = #{manufacturerId}
and cc.lease_channel != 40

mapper.update:
UPDATE HLS_ASSET_CLASS_LINE t
SET t.review_level = #{reviewLevel}
WHERE t.class_head_id = #{classHeadId}
  and t.contract_number = #{contractNumber}

UPDATE HLS_ASSET_CLASS_LINE t
SET t.approve_review_level = #{approveReviewLevel}
WHERE t.class_head_id = #{classHeadId}
  and t.contract_number = #{contractNumber}
